"""2. Final circuits: expected gates, exact equivalence, size, count, and depth.

These tests call the real passes. The public constructor is tested at the end,
separately, so its reporting bugs do not hide the algorithm's results.
"""
from math import pi
import random

import numpy as np
import pytest


# Arguments: qubit count, input instructions, expected instructions,
#            expected operation histogram, raw DAG size, expected DAG depth.
# This is explicit test data, not expected output generated by a transpiler.
LOCAL_CASES = [
    pytest.param(2, [], [], {}, 0, 0, id="empty"),
    pytest.param(1, [("h", 0), ("h", 0)], [], {}, 0, 0, id="HH"),
    pytest.param(1, [("x", 0), ("x", 0)], [], {}, 0, 0, id="XX"),
    pytest.param(2, [("cx", 0, 1), ("cx", 0, 1)], [], {}, 0, 0, id="CX-CX"),
    pytest.param(1, [("h", 0), ("x", 0)], [("h", 0), ("x", 0)],
                 {"h": 1, "x": 1}, 2, 2, id="H-X-do-not-cancel"),
    pytest.param(2, [("cx", 0, 1), ("cx", 1, 0)], [("cx", 0, 1), ("cx", 1, 0)],
                 {"cx": 2}, 2, 2, id="reversed-CX-do-not-cancel"),
    pytest.param(2, [("h", 0), ("x", 1), ("h", 0)], [("x", 1)],
                 {"x": 1}, 1, 1, id="independent-wire"),
    pytest.param(1, [("rz", 0.2, 0), ("rz", 0.5, 0)], [("rz", 0.7, 0)],
                 {"rz": 1}, 1, 1, id="RZ-sum"),
    pytest.param(2, [("rz", 0.2, 0), ("rz", 0.3, 1), ("rz", 0.4, 0)],
                 [("rz", 0.6, 0), ("rz", 0.3, 1)], {"rz": 2}, 2, 1,
                 id="parallel-RZ-gates"),
    pytest.param(3, [("h", 0), ("x", 1), ("h", 0), ("x", 1), ("h", 2)],
                 [("h", 2)], {"h": 1}, 1, 1, id="preserve-idle-wires"),
    pytest.param(2, [("rz", 0.2, 0), ("h", 0), ("cx", 0, 1),
                     ("cx", 0, 1), ("h", 0), ("rz", 0.3, 0)],
                 [("rz", 0.5, 0)], {"rz": 1}, 1, 1, id="nested-cleanup"),
    pytest.param(1, [("rz", 0.2, 0), ("h", 0), ("rz", 0.3, 0)],
                 [("rz", 0.2, 0), ("h", 0), ("rz", 0.3, 0)],
                 {"rz": 2, "h": 1}, 3, 3, id="H-blocks-RZ-merge"),
]


SEARCH_CASES = [
    pytest.param(2, [("cx", 0, 1), ("rz", 0.5, 0), ("cx", 0, 1)],
                 [("rz", 0.5, 0)], {"rz": 1}, 1, 1, id="CX-RZ-control-CX"),
    pytest.param(2, [("cx", 0, 1), ("x", 1), ("cx", 0, 1)],
                 [("x", 1)], {"x": 1}, 1, 1, id="CX-X-target-CX"),
    pytest.param(2, [("rz", 0.2, 0), ("cx", 0, 1), ("rz", 0.3, 0)],
                 [("rz", 0.5, 0), ("cx", 0, 1)], {"rz": 1, "cx": 1}, 2, 2,
                 id="RZ-merges-through-control"),
    pytest.param(2, [("x", 1), ("cx", 0, 1), ("x", 1)],
                 [("cx", 0, 1)], {"cx": 1}, 1, 1, id="X-target-CX-X-target"),
    pytest.param(3, [("cx", 0, 1), ("cx", 0, 2), ("cx", 0, 1)],
                 [("cx", 0, 2)], {"cx": 1}, 1, 1, id="shared-CX-control"),
    pytest.param(3, [("cx", 0, 2), ("cx", 1, 2), ("cx", 0, 2)],
                 [("cx", 1, 2)], {"cx": 1}, 1, 1, id="shared-CX-target"),
    pytest.param(2, [("cx", 0, 1), ("rz", 0.3, 0), ("x", 1), ("cx", 0, 1)],
                 [("rz", 0.3, 0), ("x", 1)], {"rz": 1, "x": 1}, 2, 1,
                 id="two-neutral-commutations"),
]


class TestFinalLocalResults:
    @pytest.mark.parametrize("method", ["greedy_optimize", "full_optimize"])
    @pytest.mark.parametrize("n,ops,expected_ops,counts,size,depth", LOCAL_CASES)
    def test_exact_result(self, engine, tools, method, n, ops, expected_ops, counts, size, depth):
        source = tools.circuit(n, ops)
        expected = tools.circuit(n, expected_ops)
        result = tools.run(engine, method, source)
        tools.assert_output(source, result, counts=counts, size=size, depth=depth, expected=expected)


class TestFinalSearchResults:
    @pytest.mark.parametrize("n,ops,expected_ops,counts,size,depth", SEARCH_CASES)
    def test_commutation_enables_expected_result(
        self, engine, tools, n, ops, expected_ops, counts, size, depth
    ):
        source = tools.circuit(n, ops)
        result = engine.full_optimize(tools.to_dag(source), beam_width=8, max_depth=3)
        tools.assert_output(source, result, counts=counts, size=size, depth=depth,
                            expected=tools.circuit(n, expected_ops))

    @pytest.mark.parametrize("max_depth,expected_cx", [(0, 2), (1, 2), (2, 0)])
    def test_neutral_states_are_needed_before_a_benefit(self, engine, tools, max_depth, expected_cx):
        source = tools.circuit(2, [
            ("cx", 0, 1), ("rz", 0.3, 0), ("x", 1), ("cx", 0, 1),
        ])
        result = engine.full_optimize(tools.to_dag(source), beam_width=8, max_depth=max_depth)
        tools.assert_exact(source, result)
        assert result.count_ops().get("cx", 0) == expected_cx
        if max_depth == 2:
            assert dict(result.count_ops()) == {"rz": 1, "x": 1}

    @pytest.mark.parametrize("seed", range(10))
    def test_small_random_circuits_preserve_semantics_and_greedy_baseline(self, engine, tools, seed):
        rng = random.Random(seed)
        ops = []
        for _ in range(12):
            name = rng.choice(["h", "x", "rz", "cx"])
            if name == "cx":
                control, target = rng.sample(range(3), 2)
                ops.append((name, control, target))
            elif name == "rz":
                ops.append((name, rng.choice([-pi, -0.4, 0.125, 0.7, pi]), rng.randrange(3)))
            else:
                ops.append((name, rng.randrange(3)))
        # Guaranteed adjacent improvements, regardless of the random prefix.
        ops += [("h", 0), ("h", 0), ("rz", 0.125, 1), ("rz", 0.25, 1)]
        source = tools.circuit(3, ops, phase=0.173)
        greedy = engine.greedy_optimize(tools.to_dag(source))
        result = engine.full_optimize(tools.to_dag(source), beam_width=4, max_depth=2)
        tools.assert_exact(source, result)
        tools.assert_shape_preserved(source, result)
        assert set(result.count_ops()) <= {"h", "x", "rz", "cx"}
        assert result.size() <= len(ops) - 3
        # Do not require a global optimum, or that beam width monotonically helps.
        assert tools.cost(result) <= tools.cost(greedy)


class TestReportedResults:
    @pytest.mark.parametrize("ops,counts,size,depth", [
        ([], {}, 0, 0),
        ([("h", 0), ("h", 0)], {}, 0, 0),
        ([("cx", 0, 1), ("rz", 0.5, 0), ("cx", 0, 1)], {"rz": 1}, 1, 1),
        ([("h", 0), ("x", 1)], {"h": 1, "x": 1}, 2, 1),
    ], ids=["empty", "all-cancelled", "search-required", "parallel-gates"])
    def test_public_constructor_reports_verified_result(self, optimizer_class, tools, ops, counts, size, depth):
        source = tools.circuit(2, ops)
        input_dag = tools.to_dag(source)
        instance = optimizer_class(input_dag)
        assert isinstance(instance.orig_norm_dag, tools.DAGCircuit), "Remove trailing assignment commas"
        assert isinstance(instance.optim_dag, tools.DAGCircuit), "optim_dag must not be a tuple"
        assert type(instance.gate_count) is int, "gate_count must be an integer, not a tuple/bool"
        assert type(instance.depth) is int, "depth must be an integer, not a tuple/bool"
        assert isinstance(instance.equiv_check, (bool, np.bool_))
        tools.assert_output(source, instance.optim_dag, counts=counts, size=size, depth=depth)
        assert instance.gate_count == size
        assert instance.depth == depth
        assert bool(instance.equiv_check) is True
        tools.assert_same_dag(source, input_dag)
        tools.assert_same_dag(source, instance.orig_norm_dag)

    def test_metrics_refer_to_output_not_input(self, optimizer_class, tools):
        source = tools.circuit(2, [
            ("h", 0), ("h", 0), ("rz", 0.2, 1), ("rz", 0.3, 1), ("h", 1),
        ])
        instance = optimizer_class(tools.to_dag(source))
        tools.assert_output(source, instance.optim_dag, counts={"rz": 1, "h": 1}, size=2, depth=2)
        assert instance.gate_count == 2
        assert instance.depth == 2
        assert bool(instance.equiv_check) is True

    def test_constructor_with_bound_parameters(self, optimizer_class, tools):
        from qiskit.circuit import Parameter
        theta = Parameter("theta")
        symbolic = tools.circuit(1, [("rz", theta, 0), ("rz", 0.3, 0)])
        source = symbolic.assign_parameters({theta: 0.2})
        instance = optimizer_class(tools.to_dag(source))
        tools.assert_output(source, instance.optim_dag, counts={"rz": 1}, size=1, depth=1)
        assert bool(instance.equiv_check) is True
